package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(reader, &n)
	a := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Fscan(reader, &a[i])
	}
	best := -1
	for i := 0; i < n; i++ {
		for j := i; j < n; j++ {
			cnt := 0
			for k := 0; k < n; k++ {
				v := a[k]
				if k >= i && k <= j {
					v = 1 - v
				}
				cnt += v
			}
			if cnt > best {
				best = cnt
			}
		}
	}
	fmt.Println(best)
}
